function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 100) return 'word needs 1 to 100 letters.';
  if (!/^[a-z]+$/.test(word)) return 'word may contain only lowercase letters a to z.';
  return null;
}

