function removeAlmostEqualCharacters(word) {
  let operations = 0;
  let i = 1;
  while (i < word.length) {
    const gap = Math.abs(word.charCodeAt(i) - word.charCodeAt(i - 1));
    if (gap <= 1) {
      operations++;
      i += 2;
    } else {
      i++;
    }
  }
  return operations;
}

