function removeAlmostEqualCharacters(word) {
  // cost[c] = fewest changes so far when the current position ends up as letter c.
  let cost = [];
  for (let c = 0; c < 26; c++) cost.push(word.charCodeAt(0) - 97 === c ? 0 : 1);
  for (let k = 1; k < word.length; k++) {
    const next = [];
    for (let c = 0; c < 26; c++) {
      let best = Infinity;
      for (let p = 0; p < 26; p++) if (Math.abs(p - c) > 1) best = Math.min(best, cost[p]);
      next.push(best + (word.charCodeAt(k) - 97 === c ? 0 : 1));
    }
    cost = next;
  }
  return Math.min(...cost);
}

