function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  const width = [2, 3, 5, 26][Math.floor(rand() * 4)];
  const start = Math.floor(rand() * (27 - width));
  let word = '';
  for (let k = 0; k < n; k++) word += String.fromCharCode(97 + start + Math.floor(rand() * width));
  return [word];
}
